#ifndef XOMBE_DSP_TABLES_H
#define XOMBE_DSP_TABLES_H

/* constant-argument trigonometry, roots, and init-time tables, generated by scripts/gen_dsp_tables.py */

#include "../state.h"
#include "tables.h"

#define XOMBE_GRAIN_RAMP 16 /* grain fade length, samples */

/* DCT-II kernels cos(pi*m*(i + 1/2)/J): 8-point one between PRBA vector and block means, and one per spectral
   block length J 1..XOMBE_DCT_BLK_J_MAX for m = 0..XOMBE_DCT_BLK_ROWS - 1
   block J's kernel starts at xombe__dct_blk + xombe__dct_blk_off[J], row m at offset m*J */
#define XOMBE_DCT_BLK_J_MAX 17
#define XOMBE_DCT_BLK_ROWS 6
#define XOMBE_DCT_BLK_SIZE (XOMBE_DCT_BLK_ROWS * XOMBE_DCT_BLK_J_MAX * (XOMBE_DCT_BLK_J_MAX + 1) / 2)
extern const float xombe__dct8[8][8];
extern const unsigned short xombe__dct_blk_off[XOMBE_DCT_BLK_J_MAX + 1];
extern const float xombe__dct_blk[XOMBE_DCT_BLK_SIZE];

/* cos, sin of pi*j/XOMBE_GRAIN_RAMP: grain fades at integer offsets, rotated by the grain's fractional start */
extern const float xombe__ramp_cos[XOMBE_GRAIN_RAMP];
extern const float xombe__ramp_sin[XOMBE_GRAIN_RAMP];

/* half-frame crossfades: sqrt(n/N) = xombe__sqrt_n[n] * xombe__rsqrt_half[N - XOMBE_HALF_MIN] */
extern const float xombe__sqrt_n[XOMBE_HALF_MAX + 1];
extern const float xombe__rsqrt_half[XOMBE_HALF_MAX - XOMBE_HALF_MIN + 1];

/* 1/2*log2(L), per-harmonic share of the frame gain, entry 0 unused */
extern const float xombe__half_log2[XOMBE_LMAX + 1];

/* sqrt(xombe__w0[b]*xombe__w0[b + 1]), log-scale midpoint of neighbouring pitches */
extern const float xombe__w0_mid[XOMBE_B0_COUNT - 1];

/* FFT twiddles exp(-2*pi*i*k/XOMBE_TW_N), an n-point transform takes every (XOMBE_TW_N/n)-th */
#define XOMBE_TW_N 1024
extern const xombe_cpx xombe__fft_tw[XOMBE_TW_N / 2];

#if XOMBE_HAVE_ENCODER
/* base analysis window, Hamming 0.54 - 0.46*cos(2*pi*i/(n - 1)) */
extern const float xombe__base_win[XOMBE_BASE_WINDOW];
/* pitch tracker low-pass, quarter-band sinc under a Hamming taper, unit DC gain */
extern const float xombe__pitch_lpf[2 * XOMBE_PITCH_LPF_HALF + 1];
/* pitch tracker window w^2/sum(w^2) for Hamming w of XOMBE_PITCH_WIN, and the sum of its squares */
extern const float xombe__pitch_w2[XOMBE_PITCH_WIN];
extern const float xombe__pitch_sum_w4;
#if XOMBE_KERNELS_Q15
/* xombe__pitch_w2[0..XOMBE_PITCH_HALF] * xombe__pitch_w2_q15_gain rounded (peak 32767), the rest mirrors it
   (kern_q15_pitch.c) */
extern const int16_t xombe__pitch_w2_q15[XOMBE_PITCH_HALF + 1];
extern const float xombe__pitch_w2_q15_gain;
#endif
#if XOMBE_KERNELS_Q15
/* pitch low-pass taps for kern_q15_pitch.c, g[m] = h[2*XOMBE_PITCH_LPF_HALF - m] * xombe__pitch_lpf_q15_gain rounded,
   as int16 pairs, row 0 (g[0], g[1]), (g[2], g[3]), ... zero-padded, row 1 one later, (0, g[0]), (g[1], g[2]), ... */
#define XOMBE_PITCH_LPF_PAIRS (XOMBE_PITCH_LPF_HALF + 1)
extern const uint32_t xombe__pitch_lpf_q15[2][XOMBE_PITCH_LPF_PAIRS];
extern const float xombe__pitch_lpf_q15_gain;
/* encoder analysis FFT twiddles for XOMBE_FFT / 2 complex points (kern_q15_spec.c), exp(-2*pi*i*j/(XOMBE_FFT / 2))
   for j < XOMBE_FFT / 4, Q15 rounded and held below 1, as int16 pairs (re, im) */
extern const uint32_t xombe__fft_tw_q15[XOMBE_FFT / 4];
/* tone detector FFT twiddles for XOMBE_TONE_FFT / 2 complex points (tone_detect.c), as xombe__fft_tw_q15 */
extern const uint32_t xombe__tone_tw_q15[XOMBE_TONE_FFT / 4];
#endif
/* tone detector Hann window, 0.5 - 0.5*cos(2*pi*i/(n - 1)) */
extern const float xombe__tone_win[XOMBE_TONE_SEG];
#endif

#endif
